CREATE SCHEMA IF NOT EXISTS p006_registry;
SET search_path=p006_registry,public;
CREATE TABLE IF NOT EXISTS schema_version(version integer PRIMARY KEY, installed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer(id uuid PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_access(customer_id uuid REFERENCES customer(id), account_id varchar REFERENCES public.dt_project_account(account_id), access_role text NOT NULL CHECK(access_role IN('VIEWER','EDITOR')), PRIMARY KEY(customer_id,account_id));
CREATE TABLE IF NOT EXISTS plant(id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customer(id), code text NOT NULL, name text NOT NULL, UNIQUE(customer_id,code));
CREATE TABLE IF NOT EXISTS line(id uuid PRIMARY KEY, plant_id uuid NOT NULL REFERENCES plant(id), code text NOT NULL, name text NOT NULL, UNIQUE(plant_id,code));
CREATE TABLE IF NOT EXISTS process(id uuid PRIMARY KEY, line_id uuid NOT NULL REFERENCES line(id), code text NOT NULL, name text NOT NULL, UNIQUE(line_id,code));
CREATE TABLE IF NOT EXISTS equipment_type(code text PRIMARY KEY, name text NOT NULL, english_name text, role text, legacy_mapping jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS manufacturer(id uuid PRIMARY KEY, name text NOT NULL, normalized_name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS equipment_model(id uuid PRIMARY KEY, manufacturer_id uuid NOT NULL REFERENCES manufacturer(id), name text NOT NULL, normalized_name text NOT NULL, equipment_type_code text NOT NULL REFERENCES equipment_type(code), shape_family text, specification jsonb NOT NULL DEFAULT '{}', UNIQUE(manufacturer_id,normalized_name));
CREATE TABLE IF NOT EXISTS model_option(id uuid PRIMARY KEY, model_id uuid NOT NULL REFERENCES equipment_model(id), name text NOT NULL, parameters jsonb NOT NULL DEFAULT '{}', UNIQUE(model_id,name));
CREATE TABLE IF NOT EXISTS asset(id text PRIMARY KEY, name text NOT NULL, english_name text, category text, purpose text, entry_usd text, source_usd text, base_usd text, variant jsonb NOT NULL DEFAULT '{}', image text, model_xyz_m jsonb, metadata jsonb NOT NULL, seed_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS model_asset(model_id uuid REFERENCES equipment_model(id), asset_id text REFERENCES asset(id), option_id uuid REFERENCES model_option(id), review jsonb NOT NULL DEFAULT '{}', id uuid PRIMARY KEY, UNIQUE(model_id,asset_id,option_id));
CREATE UNIQUE INDEX IF NOT EXISTS model_asset_default ON model_asset(model_id,asset_id) WHERE option_id IS NULL;
CREATE TABLE IF NOT EXISTS equipment_instance(id uuid PRIMARY KEY, process_id uuid NOT NULL REFERENCES process(id), equipment_type_code text NOT NULL REFERENCES equipment_type(code), code text NOT NULL, name text NOT NULL, model_id uuid REFERENCES equipment_model(id), option_id uuid REFERENCES model_option(id), serial_number text, management_number text, dimensions_mm jsonb NOT NULL DEFAULT '{}', installation jsonb NOT NULL DEFAULT '{}', workpiece jsonb NOT NULL DEFAULT '{}', io jsonb NOT NULL DEFAULT '{}', shape_family text, purpose text, source_identity text NOT NULL DEFAULT 'UNVERIFIED', verification jsonb NOT NULL DEFAULT '{}', match_grade text NOT NULL DEFAULT 'BLOCKED' CHECK(match_grade IN('EXACT_MATCH','CLOSE_MATCH','REFERENCE_MATCH','NO_MATCH','BLOCKED')), match_result jsonb NOT NULL DEFAULT '{}', matched_asset_id text REFERENCES asset(id), connected_asset_id text REFERENCES asset(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(process_id,code));
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY, instance_id uuid NOT NULL REFERENCES equipment_instance(id), kind text NOT NULL CHECK(kind IN('PHOTO','DRAWING','MANUAL','DIMENSION','GEOMETRY','PORT','FUNCTION','IDENTITY','OTHER')), name text NOT NULL, source_uri text, sha256 text, storage_name text, mime text, bytes bigint, review_status text NOT NULL DEFAULT 'UNREVIEWED', review_note text, created_by varchar NOT NULL REFERENCES public.dt_project_account(account_id), reviewed_by varchar REFERENCES public.dt_project_account(account_id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS new_asset_candidate(id uuid PRIMARY KEY, instance_id uuid NOT NULL UNIQUE REFERENCES equipment_instance(id), status text NOT NULL DEFAULT 'OPEN', reason jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, account_id varchar REFERENCES public.dt_project_account(account_id), customer_id uuid REFERENCES customer(id), action text NOT NULL, entity_id text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS plant_customer ON plant(customer_id);
CREATE INDEX IF NOT EXISTS line_plant ON line(plant_id);
CREATE INDEX IF NOT EXISTS process_line ON process(line_id);
CREATE INDEX IF NOT EXISTS instance_process ON equipment_instance(process_id,id);
CREATE INDEX IF NOT EXISTS instance_type ON equipment_instance(equipment_type_code);
CREATE INDEX IF NOT EXISTS instance_model ON equipment_instance(model_id);
CREATE INDEX IF NOT EXISTS instance_grade ON equipment_instance(match_grade);
CREATE INDEX IF NOT EXISTS instance_asset ON equipment_instance(connected_asset_id);
CREATE INDEX IF NOT EXISTS evidence_instance ON evidence(instance_id);
CREATE INDEX IF NOT EXISTS asset_search ON asset USING gin(to_tsvector('simple',coalesce(name,'')||' '||coalesce(english_name,'')||' '||coalesce(purpose,'')));
CREATE OR REPLACE VIEW instance_view AS SELECT e.*,p.code process_code,p.name process_name,l.code line_code,l.name line_name,f.code plant_code,f.name plant_name,c.id customer_id,c.code customer_code,c.name customer_name,m.name model_name, mf.name manufacturer_name,o.name option_name,a.name asset_name,a.entry_usd,a.image FROM equipment_instance e JOIN process p ON p.id=e.process_id JOIN line l ON l.id=p.line_id JOIN plant f ON f.id=l.plant_id JOIN customer c ON c.id=f.customer_id LEFT JOIN equipment_model m ON m.id=e.model_id LEFT JOIN manufacturer mf ON mf.id=m.manufacturer_id LEFT JOIN model_option o ON o.id=e.option_id LEFT JOIN asset a ON a.id=e.matched_asset_id;
INSERT INTO schema_version(version) VALUES(1) ON CONFLICT DO NOTHING;
